class PushTexts {
  final Map<String, String> table;
  const PushTexts(this.table);
  String operator [](String key) => table[key] ?? key;
  String get active => table["active"]!;
  String get blocked => table["blocked"]!;
  String get checking => table["checking"]!;
  String get conflict => table["conflict"]!;
  String get delivery => table["delivery"]!;
