  String get failed => table["failed"]!;
  String get inactive => table["inactive"]!;
  String get install => table["install"]!;
  String get intro => table["intro"]!;
  String get limited => table["limited"]!;
  String get next => table["next"]!;
  String get notConfigured => table["notConfigured"]!;
  String get offline => table["offline"]!;
  String get pendingDelete => table["pendingDelete"]!;
  String get privacy => table["privacy"]!;
  String get retry => table["retry"]!;
  String get savedTime => table["savedTime"]!;
  String get syncingError => table["syncingError"]!;
  String get test => table["test"]!;
  String get testSent => table["testSent"]!;
  String get title => table["title"]!;
  String get unsupported => table["unsupported"]!;
  String get updating => table["updating"]!;
}

